--[=[
    @class IPlayerScopeService
    玩家作用域服务接口
]=]

export type IPlayerScopeService = {
    --- 获取玩家作用域
    GetPlayerScope: (playerOrUserId: Player | number) -> IServiceScope,

    --- 获取玩家作用域内指定服务
    GetServiceInPlayerScope: (playerOrUserId: Player | number, serviceType: string) -> any?,

    --- 获取玩家作用域内指定服务 (如果服务不存在, 则抛出错误)
    GetRequiredServiceInPlayerScope: (playerOrUserId: Player | number, serviceType: string) -> any,

    --- 检查玩家是否准备好
    IsPlayerReady: (playerOrUserId: Player | number) -> boolean
}

return {}
